def inr_format(n):
    s = str(n)
    if len(s) <= 3:
        return s
    reversed_s = s[::-1]
    grouped = []
    for i in range(0, len(reversed_s), 2):
        grouped.append(reversed_s[i:i+2])
    grouped = grouped[::-1]
    return ','.join(grouped[:-1]) + ',' + grouped[-1]

